const BORDER_SELECTORS = {
  "--color-message-header-contents-border": ".message-header-contents",
  "--color-topic-indent-border": "ul.topic-list.topic-list-has-topics::before",
  "--color-message-reaction-border": ".message_reaction",
  "--color-message-reaction-border-reacted": ".message_reaction.reacted",
  "--color-border-unread-counter": ".unread_count",
  "--color-border-unread-counter-popover-menu": ".popover-menu .unread_count",
};

function borderCss(theme) {
  const square = squareCorners(theme) ? "body, body * {\n  border-radius: 0 !important;\n}\n\n" : "";
  const blocks = [];
  for (const [id, row] of Object.entries(theme.borders || {})) {
    const style = borderStyle(row.style);
    const width = cssSize(row.width);
    const radius = cssSize(row.radius);
    const selector = BORDER_SELECTORS[id];
    if (!selector || (!style && !width && !radius)) continue;
    const reaction = id.includes("message-reaction-border");
    const decls = [];
    if (reaction) {
      if (style) decls.push(`  outline-style: ${style} !important;`);
      if (width) decls.push(`  outline-width: ${width} !important;`);
    } else {
      if (style) decls.push(`  border-style: ${style} !important;`);
      if (width) decls.push(`  border-width: ${width} !important;`);
    }
    if (radius) decls.push(`  border-radius: ${radius} !important;`);
    if (id === "--color-topic-indent-border") {
      decls.push("  border-right-style: none !important;");
      decls.push("  border-right-width: 0 !important;");
    }
    blocks.push(`${selector} {\n${decls.join("\n")}\n}`);
  }
  return square + (blocks.length ? `${blocks.join("\n\n")}\n\n` : "");
}

function cssColor(colors) {
  if (!colors.dark) return colors.light;
  if (!colors.light) return colors.dark;
  if (colors.light === colors.dark) return colors.light;
  return `light-dark(${colors.light}, ${colors.dark})`;
}

